require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';Auth::requireLogin();$db=Database::connect();marketplace_install($db);$id=(int)($_GET['id']??0);$s=$db->prepare("SELECT o.*,b.name branch_name FROM online_orders o LEFT JOIN branches b ON b.id=o.branch_id WHERE o.id=? AND o.payment_status='paid' LIMIT 1");$s->execute([$id]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Order paid tidak ditemukan');}$items=marketplace_order_items($db,$id);$pageTitle='Fulfillment '.$o['order_number'];$ok=flash('success');$err=flash('error');require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>"><main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1><?=e($o['order_number'])?></h1><p><?=e($o['recipient_name'])?> • <?=e($o['branch_name'])?> • <?=e(ucwords(str_replace('_',' ',$o['fulfillment_status'])))?></p></div><div class="topbar-actions"><a class="mp-btn soft" href="<?=legacy_base_url('admin/marketplace-orders/invoice.php?id='.$id)?>" target="_blank"><i class="bi bi-file-pdf"></i> Invoice PDF</a></div></header><?php if($ok):?><div class="mp-alert success"><?=e($ok)?></div><?php endif;?><?php if($err):?><div class="mp-alert error"><?=e($err)?></div><?php endif;?><section class="mp-panel"><div class="mp-panel-head"><div><h3>Picking List</h3><p>Pastikan SKU/varian dan qty sesuai sebelum packing.</p></div></div><form method="post" action="<?=legacy_base_url('admin/marketplace-fulfillment/action.php')?>" enctype="multipart/form-data"><?=CSRF::input()?><input type="hidden" name="order_id" value="<?=$id?>"><div class="table-premium-card"><table class="premium-table"><thead><tr><th>Produk</th><th>SKU</th><th>Qty Order</th><th>Picked</th><th>Packed</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><b><?=e($i['product_name'])?></b><?php if($i['variant_name']):?><br><small>Varian: <?=e($i['variant_name'])?></small><?php endif;?></td><td><?=e($i['variant_sku']?:$i['product_code'])?></td><td><?=e($i['qty'])?> <?=e($i['unit'])?></td><td><input class="mp-small-input" type="number" min="0" max="<?=$i['qty']?>" name="picked[<?=$i['id']?>]" value="<?=e($i['picked_qty'])?>"></td><td><input class="mp-small-input" type="number" min="0" max="<?=$i['qty']?>" name="packed[<?=$i['id']?>]" value="<?=e($i['packed_qty'])?>"></td></tr><?php endforeach;?></tbody></table></div><div class="mp-form"><label>Foto Bukti Packing <small>(opsional JPG/PNG/WEBP maks 5MB)</small><input type="file" name="packing_proof" accept="image/*"></label><label>Status Berikutnya<select name="fulfillment_status"><option value="picking">Picking</option><option value="packing">Packing</option><option value="ready_ship"><?= (string)$o['courier_code']==='pickup'?'Siap Diambil':'Siap Dikirim'; ?></option></select></label><button class="mp-btn" type="submit"><i class="bi bi-check2-circle"></i> Simpan Fulfillment</button></div></form><?php if($o['packing_proof']):?><div class="mp-proof"><b>Bukti packing terakhir</b><br><img src="<?=legacy_base_url($o['packing_proof'])?>" alt="Bukti packing" style="max-width:280px;border-radius:16px;margin-top:10px"></div><?php endif;?></section></main><?php require __DIR__.'/../../layouts/admin-footer.php';?>
